export enum UserRole {
  ADMIN = 'admin',
  TEACHER = 'teacher',
  STUDENT = 'student',
}

@Column({ type: 'enum', enum: UserRole, default: UserRole.STUDENT })
role: UserRole;

@Delete(':id')
@HttpCode(HttpStatus.NO_CONTENT)
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles(UserRole.ADMIN)
remove(@Param('id', ParseIntPipe) id: number) {
  return this.coursesService.remove(id);
}

@Column({ type: 'int', nullable: true })
createdByUserId: number | null;

private assertCanManage(course: Course, actor: AuthenticatedUser): void {
  if (actor.role === UserRole.ADMIN) return;
  if (actor.role === UserRole.TEACHER &&
      course.createdByUserId === actor.id) return;
  throw new ForbiddenException('You cannot modify this course');
}

export function corsOptions(config: ConfigService): CorsOptions {
  const origin = config.getOrThrow<string>('CORS_ORIGINS')
    .split(',').map((entry) => entry.trim()).filter(Boolean);
  return {
    origin,
    methods: ['GET', 'POST', 'PATCH', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  };
}

@Post('login')
@HttpCode(HttpStatus.OK)
@Throttle({ default: { limit: 5, ttl: 60_000 } })
login(@Body() dto: LoginDto) { return this.authService.login(dto); }
